import { useId } from 'react';
import { useForm } from '@tanstack/react-form';
import type { DeepKeys } from '@tanstack/react-form';

import { FieldRenderer } from '@/components/formedible/field-renderer';
import { Form as FormRoot } from '@/components/formedible/form';
import type { FormProps } from '@/components/formedible/form';
import { getValueAtFieldPath } from '@/lib/formedible/field-path';
import { normalizeFieldConfig } from '@/lib/formedible/normalize-field-config';
import { normalizeOptions } from '@/lib/formedible/normalize-options';
import type { FormedibleFormValues, UseFormedibleOptions } from '@/lib/formedible/types';
import type { NormalizedFieldConfig } from '@/lib/formedible/types';
import { buildFieldValidators, buildFormValidators } from '@/lib/formedible/validation';
import { formatValidationError } from '@/lib/formedible/zod-errors';

export function useFormedible<TFormValues extends FormedibleFormValues = FormedibleFormValues>(config: UseFormedibleOptions<TFormValues>) {
  const formId = useId();
  const normalizedOptions = normalizeOptions(config);
  const fields = normalizedOptions.fields;
  const form = useForm({
    defaultValues: config.formOptions.defaultValues,
    validators: buildFormValidators(config.schema, config.crossFieldValidation),
    onSubmit: async ({ value }) => {
      await config.formOptions.onSubmit?.({ value });
    },
  });

  function shouldRenderField(fieldConfig: NormalizedFieldConfig<TFormValues>, localValues: FormedibleFormValues | undefined) {
    if (!fieldConfig.conditional) {
      return true;
    }

    const conditionalValues = localValues ?? form.state.values;

    if (typeof fieldConfig.conditional === 'string') {
      return Boolean(getValueAtFieldPath(conditionalValues, fieldConfig.conditional));
    }

    return fieldConfig.conditional(conditionalValues as TFormValues);
  }

  function renderField(fieldConfig: NormalizedFieldConfig<TFormValues>, options?: { readonly name?: string; readonly key?: string; readonly localValues?: FormedibleFormValues }) {
    const fieldName = options?.name ?? fieldConfig.name;
    const renderConfig = fieldName === fieldConfig.name ? fieldConfig : normalizeFieldConfig<TFormValues>({ ...fieldConfig, name: fieldName });
    const localValues = options?.localValues;

    if (!shouldRenderField(fieldConfig, localValues)) {
      return null;
    }

    return (
      <form.Field
        key={options?.key ?? fieldName}
        name={fieldName as DeepKeys<TFormValues>}
        validators={buildFieldValidators<TFormValues, DeepKeys<TFormValues>>(renderConfig, config.schema, config.crossFieldValidation, config.asyncValidation)}
      >
        {(field) => {
          const error = field.state.meta.errors.map(formatValidationError).find((message) => message !== undefined);
          type FieldValueUpdate = Parameters<typeof field.handleChange>[0];

          return (
            <FieldRenderer
              fieldConfig={renderConfig}
              field={{
                id: `${formId}-${fieldName}`,
                name: fieldName,
                value: field.state.value,
                formValues: localValues ?? form.state.values,
                error,
                onBlur: field.handleBlur,
                onChange: (nextValue) => field.handleChange(nextValue as FieldValueUpdate),
              }}
              renderField={renderField}
            />
          );
        }}
      </form.Field>
    );
  }

  function Form({ className, ...props }: FormProps) {
    return (
      <FormRoot
        className={className}
        onSubmit={(event) => {
          event.preventDefault();
          event.stopPropagation();
          form.handleSubmit();
        }}
        {...props}
      >
        {fields.map((fieldConfig) => renderField(fieldConfig))}
      </FormRoot>
    );
  }

  return { Form, form };
}

import type { ComponentProps } from 'react';

import { cn } from '@/lib/utils';

export type FormProps = ComponentProps<'form'>;

export function Form({ className, ...props }: FormProps) {
  return <form className={cn(className)} {...props} />;
}

import { getFieldComponent } from '@/components/formedible/fields/field-registry';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function FieldRenderer<TFormValues extends FormedibleFormValues>(props: FormedibleFieldRenderProps<TFormValues>) {
  const FieldComponent = getFieldComponent<TFormValues>(props.fieldConfig.type);

  return <FieldComponent fieldConfig={props.fieldConfig} field={props.field} renderField={props.renderField} />;
}

import type { ReactNode } from 'react';

import { Field, FieldDescription, FieldError, FieldLabel } from '@/components/ui/field';
import type { FormedibleFieldController, FormedibleFormValues, NormalizedFieldConfig } from '@/lib/formedible/types';

export interface FieldWrapperProps<TFormValues extends FormedibleFormValues = FormedibleFormValues> {
  readonly fieldConfig: NormalizedFieldConfig<TFormValues>;
  readonly field: FormedibleFieldController;
  readonly children: ReactNode;
}

export function FieldWrapper<TFormValues extends FormedibleFormValues>({ fieldConfig, field, children }: FieldWrapperProps<TFormValues>) {
  return (
    <Field
      className={fieldConfig.className}
      data-disabled={fieldConfig.disabled ? 'true' : undefined}
      data-invalid={field.error ? 'true' : undefined}
    >
      {fieldConfig.label ? (
        <FieldLabel htmlFor={field.id}>
          {fieldConfig.label}
          {fieldConfig.required ? <span aria-hidden="true"> *</span> : undefined}
        </FieldLabel>
      ) : undefined}
      {children}
      {fieldConfig.description ? <FieldDescription>{fieldConfig.description}</FieldDescription> : undefined}
      {field.error ? <FieldError>{field.error}</FieldError> : undefined}
    </Field>
  );
}

import { Input as TextInput } from '@/components/ui/input';
import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

const textInputTypes = ['email', 'password', 'url', 'tel'] as const;

function getInputType(type: string) {
  return textInputTypes.some((inputType) => inputType === type) ? type : 'text';
}

export function TextField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const value = typeof field.value === 'string' ? field.value : '';

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <TextInput
        id={field.id}
        name={field.name}
        type={getInputType(fieldConfig.type)}
        value={value}
        placeholder={fieldConfig.placeholder}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onChange={(event) => field.onChange(event.target.value)}
      />
    </FieldWrapper>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Textarea } from '@/components/ui/textarea';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function TextareaField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const value = typeof field.value === 'string' ? field.value : '';

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <Textarea
        id={field.id}
        name={field.name}
        value={value}
        placeholder={fieldConfig.placeholder}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        rows={fieldConfig.rows}
        maxLength={fieldConfig.maxLength}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onChange={(event) => field.onChange(event.target.value)}
      />
    </FieldWrapper>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function NumberField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const value = typeof field.value === 'number' || typeof field.value === 'string' ? field.value : '';

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <Input
        id={field.id}
        name={field.name}
        type="number"
        value={value}
        placeholder={fieldConfig.placeholder}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        min={fieldConfig.min}
        max={fieldConfig.max}
        step={fieldConfig.step}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onChange={(event) => field.onChange(event.target.value === '' ? undefined : event.target.valueAsNumber)}
      />
    </FieldWrapper>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { resolveFieldOptions } from '@/components/formedible/fields/advanced-field-utils';
import { Select, SelectContent, SelectGroup, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function SelectField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const value = typeof field.value === 'string' ? field.value : '';
  const options = resolveFieldOptions(fieldConfig, field.formValues);

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <Select value={value} disabled={fieldConfig.disabled} required={fieldConfig.required} onValueChange={field.onChange}>
        <SelectTrigger id={field.id} name={field.name} aria-invalid={field.error ? true : undefined} className={fieldConfig.inputClassName} onBlur={field.onBlur}>
          <SelectValue placeholder={fieldConfig.placeholder} />
        </SelectTrigger>
        <SelectContent>
          <SelectGroup>
            {options.map((option) => (
              <SelectItem key={option.value} value={option.value} disabled={option.disabled}>
                {option.label}
              </SelectItem>
            ))}
          </SelectGroup>
        </SelectContent>
      </Select>
    </FieldWrapper>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Checkbox } from '@/components/ui/checkbox';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function CheckboxField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const checked = field.value === true;

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <Checkbox
        id={field.id}
        name={field.name}
        checked={checked}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onCheckedChange={(nextChecked) => field.onChange(nextChecked === true)}
      />
    </FieldWrapper>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Switch } from '@/components/ui/switch';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function SwitchField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const checked = field.value === true;

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <Switch
        id={field.id}
        name={field.name}
        checked={checked}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onCheckedChange={field.onChange}
      />
    </FieldWrapper>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { resolveFieldOptions } from '@/components/formedible/fields/advanced-field-utils';
import { Field, FieldLabel } from '@/components/ui/field';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function RadioField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const value = typeof field.value === 'string' ? field.value : '';
  const options = resolveFieldOptions(fieldConfig, field.formValues);

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <RadioGroup
        id={field.id}
        name={field.name}
        value={value}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onValueChange={field.onChange}
      >
        {options.map((option) => {
          const optionId = `${field.id}-${option.value}`;

          return (
            <Field key={option.value} className="flex flex-row items-center gap-2">
              <RadioGroupItem id={optionId} value={option.value} disabled={option.disabled} />
              <FieldLabel htmlFor={optionId}>{option.label}</FieldLabel>
            </Field>
          );
        })}
      </RadioGroup>
    </FieldWrapper>
  );
}

import { Input } from '@/components/ui/input';
import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import type { FormedibleFormValues, FormedibleFieldRenderProps } from '@/lib/formedible/types';

function toDateInputValue(value: unknown): string {
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return value.toISOString().slice(0, 10);
  }

  return typeof value === 'string' ? value.slice(0, 10) : '';
}

function toDateBound(value: Date | string | undefined): string | undefined {
  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return value.toISOString().slice(0, 10);
  }

  return typeof value === 'string' ? value.slice(0, 10) : undefined;
}

export function DateField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const value = toDateInputValue(field.value);
  const dateConfig = fieldConfig.dateConfig;

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <Input
        id={field.id}
        name={field.name}
        type="date"
        value={value}
        min={toDateBound(dateConfig?.minDate)}
        max={toDateBound(dateConfig?.maxDate)}
        placeholder={fieldConfig.placeholder}
        disabled={fieldConfig.disabled}
        required={fieldConfig.required}
        aria-invalid={field.error ? true : undefined}
        className={fieldConfig.inputClassName}
        onBlur={field.onBlur}
        onChange={(event) => {
          const nextValue = event.target.value;
          const nextDate = new Date(`${nextValue}T00:00:00`);

          if (dateConfig?.disableDate?.(nextDate, (field.formValues ?? {}) as TFormValues)) {
            return;
          }

          field.onChange(nextValue);
        }}
      />
    </FieldWrapper>
  );
}

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { getNumber } from '@/components/formedible/fields/advanced-field-utils';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function SliderField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.sliderConfig;
  const min = config?.min ?? fieldConfig.min ?? 0;
  const max = config?.max ?? fieldConfig.max ?? 100;
  const step = config?.step ?? fieldConfig.step ?? 1;
  const value = getNumber(field.value, min);
  const mappingItem = config?.valueMapping?.find((item) => item.sliderValue === value);
  const displayValue = mappingItem?.displayValue ?? value.toFixed(config?.valueDisplayPrecision ?? 0);
  const VisualizationComponent = config?.visualizationComponent;
  const label = fieldConfig.label && config?.showValue !== false ? `${fieldConfig.label} (${config?.valueLabelPrefix ?? ''}${displayValue}${config?.valueLabelSuffix ?? ''})` : fieldConfig.label;

  return (
    <FieldWrapper fieldConfig={{ ...fieldConfig, label }} field={field}>
      <div className="space-y-3">
        {config?.showRawValue && <div className="text-xs text-muted-foreground">Raw: {value}</div>}
        {VisualizationComponent && config?.valueMapping && (
          <div className="flex items-center justify-between gap-2">
            {config.valueMapping.map((item) => (
              <Button key={item.sliderValue} type="button" variant="ghost" disabled={fieldConfig.disabled} onClick={() => field.onChange(item.sliderValue)}>
                <VisualizationComponent value={item.sliderValue} displayValue={item.displayValue} label={item.label} isActive={value === item.sliderValue} />
              </Button>
            ))}
          </div>
        )}
        <InputRange
          id={field.id}
          name={field.name}
          min={min}
          max={max}
          step={step}
          value={value}
          disabled={fieldConfig.disabled}
          invalid={field.error !== undefined}
          className={fieldConfig.inputClassName}
          onBlur={field.onBlur}
          onChange={field.onChange}
        />
        {config?.marks && config.marks.length > 0 && (
          <div className="flex justify-between text-xs text-muted-foreground">
            {config.marks.map((mark) => (
              <span key={mark.value}>{mark.label}</span>
            ))}
          </div>
        )}
        {mappingItem?.label && <div className="text-center text-sm text-muted-foreground">{mappingItem.label}</div>}
      </div>
    </FieldWrapper>
  );
}

interface InputRangeProps {
  readonly id: string;
  readonly name: string;
  readonly min: number;
  readonly max: number;
  readonly step: number;
  readonly value: number;
  readonly disabled: boolean;
  readonly invalid: boolean;
  readonly className?: string;
  readonly onBlur: () => void;
  readonly onChange: (value: number) => void;
}

function InputRange({ id, name, min, max, step, value, disabled, invalid, className, onBlur, onChange }: InputRangeProps) {
  return <Slider id={id} name={name} min={min} max={max} step={step} value={value} disabled={disabled} aria-invalid={invalid ? true : undefined} className={className} onBlur={onBlur} onValueChange={onChange} />;
}

import { Heart, Star, ThumbsUp } from 'lucide-react';
import { useState } from 'react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { getNumber } from '@/components/formedible/fields/advanced-field-utils';
import { Button } from '@/components/ui/button';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

const icons = { star: Star, heart: Heart, thumbs: ThumbsUp } as const;
const sizes = { sm: 'size-4', md: 'size-6', lg: 'size-8' } as const;

export function RatingField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.ratingConfig;
  const max = config?.max ?? 5;
  const icon = config?.icon ?? 'star';
  const Icon = icons[icon];
  const value = getNumber(field.value, 0);
  const [hoverValue, setHoverValue] = useState<number | undefined>();
  const activeValue = hoverValue ?? value;

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="space-y-2">
        {config?.showValue && <div className="text-xs text-muted-foreground">({value}/{max})</div>}
        <div className="flex items-center gap-1" role="radiogroup" aria-label={typeof fieldConfig.label === 'string' ? fieldConfig.label : field.name}>
          {Array.from({ length: max }, (_, index) => {
            const rating = index + 1;
            const halfRating = index + 0.5;
            const isFilled = activeValue >= rating || (config?.allowHalf === true && activeValue >= halfRating);

            return (
              <span key={rating} className="relative inline-flex">
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  role="radio"
                  aria-checked={value === rating}
                  disabled={fieldConfig.disabled}
                  className="transition-transform hover:scale-110 disabled:cursor-not-allowed disabled:opacity-50"
                  onBlur={field.onBlur}
                  onClick={() => field.onChange(rating)}
                  onMouseEnter={() => setHoverValue(rating)}
                  onMouseLeave={() => setHoverValue(undefined)}
                >
                  <Icon className={cn(sizes[config?.size ?? 'md'], isFilled ? activeClass(icon) : 'text-muted-foreground')} />
                </Button>
                {config?.allowHalf && (
                  <Button
                    type="button"
                    variant="ghost"
                    aria-label={`Rate ${halfRating}`}
                    disabled={fieldConfig.disabled}
                    className="absolute inset-y-0 left-0 h-auto w-1/2 p-0 disabled:cursor-not-allowed"
                    onClick={() => field.onChange(halfRating)}
                    onMouseEnter={() => setHoverValue(halfRating)}
                    onMouseLeave={() => setHoverValue(undefined)}
                  />
                )}
              </span>
            );
          })}
          {value > 0 && (
            <Button type="button" variant="ghost" disabled={fieldConfig.disabled} className="ml-2 h-auto text-xs text-muted-foreground hover:text-foreground" onClick={() => field.onChange(0)}>
              Clear
            </Button>
          )}
        </div>
      </div>
    </FieldWrapper>
  );
}

function activeClass(icon: 'star' | 'heart' | 'thumbs'): string {
  if (icon === 'heart') {
    return 'fill-red-500 text-red-500';
  }

  if (icon === 'thumbs') {
    return 'fill-blue-500 text-blue-500';
  }

  return 'fill-yellow-400 text-yellow-400';
}

import { Check, ChevronDown, X } from 'lucide-react';
import { useState } from 'react';

import { getStringArray, labelToText, resolveFieldOptions } from '@/components/formedible/fields/advanced-field-utils';
import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

export function MultiSelectField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.multiSelectConfig;
  const selectedValues = getStringArray(field.value);
  const options = resolveFieldOptions(fieldConfig, field.formValues);
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const maxSelections = config?.maxSelections ?? Number.POSITIVE_INFINITY;
  const searchable = config?.searchable ?? true;
  const filteredOptions = options.filter((option) => `${option.value} ${labelToText(option.label)}`.toLowerCase().includes(searchQuery.toLowerCase()));
  const canCreate = config?.creatable === true && searchQuery.trim() !== '' && !options.some((option) => option.value.toLowerCase() === searchQuery.trim().toLowerCase());
  const displayOptions = canCreate ? [{ value: searchQuery.trim(), label: `Create "${searchQuery.trim()}"` }, ...filteredOptions] : filteredOptions;

  function toggleValue(value: string) {
    if (selectedValues.includes(value)) {
      field.onChange(selectedValues.filter((selectedValue) => selectedValue !== value));
    } else if (selectedValues.length < maxSelections) {
      field.onChange([...selectedValues, value]);
    }

    setSearchQuery('');
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="relative space-y-2">
        {maxSelections < Number.POSITIVE_INFINITY && <div className="text-sm text-muted-foreground">({selectedValues.length}/{maxSelections})</div>}
        <Button
          type="button"
          variant="outline"
          disabled={fieldConfig.disabled}
          aria-expanded={isOpen}
          aria-invalid={field.error ? true : undefined}
          className={cn('min-h-9 w-full justify-start bg-transparent px-3 py-2 text-left text-sm shadow-xs disabled:cursor-not-allowed disabled:opacity-50', fieldConfig.inputClassName)}
          onClick={() => setIsOpen((open) => !open)}
          onBlur={field.onBlur}
        >
          <span className="flex flex-wrap items-center gap-1">
            {selectedValues.length === 0 && <span className="text-muted-foreground">{config?.placeholder ?? fieldConfig.placeholder ?? 'Select options...'}</span>}
            {selectedValues.map((value) => {
              const option = options.find((item) => item.value === value);
              return (
                <Badge key={value} variant="secondary" className="gap-1">
                  {option?.label ?? value}
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="size-4"
                    disabled={fieldConfig.disabled}
                    onClick={(event) => {
                      event.stopPropagation();
                      toggleValue(value);
                    }}
                  >
                    <X className="size-3" />
                  </Button>
                </Badge>
              );
            })}
            <ChevronDown className="ml-auto size-4 opacity-50" />
          </span>
        </Button>
        {isOpen && (
          <div className="absolute z-50 w-full rounded-md border bg-popover p-1 text-popover-foreground shadow-md">
            {searchable && <Input value={searchQuery} placeholder={fieldConfig.placeholder ?? 'Search options...'} className="mb-1" onChange={(event) => setSearchQuery(event.target.value)} />}
            <div className="max-h-60 overflow-y-auto">
              {displayOptions.length === 0 && <div className="p-2 text-center text-sm text-muted-foreground">{config?.noOptionsText ?? 'No options found'}</div>}
              {displayOptions.map((option) => {
                const isSelected = selectedValues.includes(option.value);
                const isDisabled = !isSelected && selectedValues.length >= maxSelections;

                return (
                  <Button
                    key={option.value}
                    type="button"
                    variant="ghost"
                    disabled={isDisabled || fieldConfig.disabled || option.disabled}
                    className="flex h-auto w-full justify-between rounded-sm px-2 py-1.5 text-left text-sm"
                    onClick={() => toggleValue(option.value)}
                  >
                    <span>{option.label}</span>
                    {isSelected && <Check className="size-4" />}
                  </Button>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </FieldWrapper>
  );
}

